import heapq

def dijkstra(graph, start, end):
    heap = [(0, start)]
    visited = set()
    costs = {start: 0}
    while heap:
        cost, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        if u == end:
            return cost
        for v, c in graph[u]:
            if v in visited:
                continue
            next_cost = cost + c
            if next_cost < costs.get(v, float("inf")):
                costs[v] = next_cost
                heapq.heappush(heap, (next_cost, v))
    return -1

