from ..utils import test_iterable
from .sort import Sort


class RecursiveMergeSort(Sort):
    """
    Time: О(N log N)
    Space: О(N)
    Stability: true

    Recursive implementation
    """

    def sort(self, xs: List[int]) -> List[int]:
        test_iterable(xs)
        if len(xs) <= 1:
            return xs

        mid = len(xs) // 2
        left = xs[:mid]
        right = xs[mid:]

        return self.merge(self.sort(left), self.sort(right))

    @staticmethod
    def merge(left: List[int], right: List[int]) -> List[int]:
        xs = []
        while not (len(left) == 0 or len(right) == 0):
            if left[0] <= right[0]:
                xs.append(left.pop(0))
            else:
                xs.append(right.pop(0))
        return xs + left + right

def merge(left, right):
    if not len(left) or not len(right): # Input arguments may be None type
        return left or right

    len_left = len(left)
    len_right = len(right)
    result = []
    i = 0
    j = 0
    while (len(result) < len_left + len_right):
        if left[i] < right[j]:
            result.append(left[i])
            i+=1
        else:
            result.append(right[j])
            j+=1
        if i == len_left or j == len_right:
            result.extend(left[i:] or right[j:])
            break
    return result

def merge_sort(input_list):
    if len(input_list) < 2:
        return input_list
    else:
        mid = int(len(input_list)/2)
        left = merge_sort(input_list[:mid])
        right = merge_sort(input_list[mid:])

    return merge(left, right)

if __name__ == '__main__':
    result = merge_sort([1,3,2,19,1,3,12,4])
    print(result)

from typing import List

from ..utils import test_iterable
from .sort import Sort


class QuickSort(Sort):
    """
    Worst-case: О(n^2)
    Best-case: O(n log n)
    Average: O(n log n)
    Space: О(n) naive
    Stability: no
    """

    def sort(self, xs: List[int]) -> List[int]:
        test_iterable(xs)

        top = {0: 0}
        bottom = {0: len(xs)}
        i = 0

        while i >= 0:
            l = top[i]
            r = bottom[i] - 1
            if l < r:
                pivot = xs[l]
                while l < r:
                    while xs[r] >= pivot and l < r:
                        r -= 1
                    if l < r:
                        xs[l] = xs[r]
                        l += 1
                    while xs[l] <= pivot and l < r:
                        l += 1
                    if l < r:
                        xs[r] = xs[l]
                        r -= 1
                xs[l] = pivot
                top[i + 1] = l + 1
                bottom[i + 1] = bottom[i]
                bottom[i] = l
                i += 1
            else:
                i -= 1

        return xs

def selection_sort(collection):
    length = len(collection)
    for i in range(length - 1):
        min_index = i
        for k in range(i + 1, length):
            if collection[k] < collection[min_index]:
                min_index = k
        if min_index != i:
            collection[i], collection[min_index] = collection[min_index], collection[i]
    return collection
